command:
$ErrorActionPreference = 'Stop'
$requestedSha = '733cd6d7078222f7e5c884ff7a890cfcd712f827'
$expectedValidationCount = 38
$repo = [string]$env:DCOIR_REPO_ROOT
$downloads = [string]$env:DCOIR_DOWNLOADS_DIR
if ([string]::IsNullOrWhiteSpace($repo)) { throw 'DCOIR_REPO_ROOT is missing' }
if ([string]::IsNullOrWhiteSpace($downloads)) { throw 'DCOIR_DOWNLOADS_DIR is missing' }
New-Item -ItemType Directory -Force -Path $downloads | Out-Null
$worktree = Join-Path $env:RUNNER_TEMP ('dcoir-pr469-' + $requestedSha.Substring(0,12))
$actualSha = ''
$results = @()
$commands = @()
$inferenceEnv = @('OPENROUTER_API_KEY','DCOIR_OPENROUTER_API_KEY','OPENAI_API_KEY','DCOIR_OPENAI_API_KEY','DCOIR_GEMINI_API')
$receiptPath = Join-Path $downloads 'validation_receipt.json'
$summaryPath = Join-Path $downloads 'summary.md'
$worktreeDirty = $true
$dirtyPaths = @()

function Invoke-DcoirValidationCommand {
  param([int]$Index, [string]$Label, [string]$CommandText)
  $safeLabel = ($Label -replace '[^A-Za-z0-9._-]', '_')
  $logPath = Join-Path $downloads (('{0:D2}-{1}.log' -f $Index, $safeLabel))
  ('COMMAND: ' + $CommandText) | Out-File -LiteralPath $logPath -Encoding utf8
  $previousEap = $ErrorActionPreference
  $exitCode = 999
  try {
    $ErrorActionPreference = 'Continue'
    & cmd.exe /d /s /c $CommandText *>> $logPath
    $exitCode = $LASTEXITCODE
  }
  finally {
    $ErrorActionPreference = $previousEap
  }
  return [pscustomobject]@{ index=$Index; label=$Label; command=$CommandText; exit_code=$exitCode; log=[IO.Path]::GetFileName($logPath) }
}

try {
  if (Test-Path -LiteralPath $worktree) {
    & git -C $repo worktree remove --force $worktree 2>$null
    if (Test-Path -LiteralPath $worktree) { Remove-Item -LiteralPath $worktree -Recurse -Force }
  }
  & git -C $repo fetch --no-tags origin $requestedSha
  if ($LASTEXITCODE -ne 0) { throw "git fetch failed with exit code $LASTEXITCODE" }
  & git -C $repo worktree add --detach $worktree $requestedSha
  if ($LASTEXITCODE -ne 0) { throw "git worktree add failed with exit code $LASTEXITCODE" }
  Set-Location -LiteralPath $worktree
  $actualSha = (& git rev-parse HEAD).Trim()
  if ($LASTEXITCODE -ne 0) { throw 'git rev-parse HEAD failed' }
  if ($actualSha -ne $requestedSha) { throw "exact-head mismatch: requested=$requestedSha actual=$actualSha" }

  foreach ($name in $inferenceEnv) { [Environment]::SetEnvironmentVariable($name, $null, 'Process') }
  foreach ($name in $inferenceEnv) {
    if (-not [string]::IsNullOrEmpty([Environment]::GetEnvironmentVariable($name, 'Process'))) { throw "inference credential remained in process environment: $name" }
  }
  $env:PYTHONDONTWRITEBYTECODE = '1'

  $capturing = $false
  foreach ($line in (Get-Content -LiteralPath '.github/dcoir_review/openrouter-pr-review-pareto.yml' -Encoding UTF8)) {
    if ($line -match '^validation_commands:\s*$') { $capturing = $true; continue }
    if (-not $capturing) { continue }
    if ($line -match '^\s{2}-\s+(.+?)\s*$') { $commands += $Matches[1]; continue }
    if ($line -match '^\S') { break }
  }
  if ($commands.Count -ne $expectedValidationCount) { throw "expected $expectedValidationCount governed validation commands, parsed $($commands.Count)" }

  $results += Invoke-DcoirValidationCommand -Index 0 -Label 'preflight-v43' -CommandText 'python3 .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v43_selftest.py'
  $index = 1
  foreach ($commandText in $commands) {
    $results += Invoke-DcoirValidationCommand -Index $index -Label ('validation-{0:D2}' -f $index) -CommandText $commandText
    $index += 1
  }

  $statusLines = @(& git status --porcelain=v1 --untracked-files=all)
  if ($LASTEXITCODE -ne 0) { throw 'git status failed' }
  $dirtyPaths = @($statusLines | ForEach-Object { if ($_.Length -gt 3) { $_.Substring(3) } else { $_ } })
  $worktreeDirty = ($dirtyPaths.Count -gt 0)
  $passedCount = @($results | Where-Object { $_.exit_code -eq 0 }).Count
  $failedCount = $results.Count - $passedCount
  $preflightPassed = ($results.Count -gt 0 -and $results[0].exit_code -eq 0)
  $resultText = if ($failedCount -eq 0 -and -not $worktreeDirty -and $preflightPassed) { 'success' } else { 'failure' }

  $receipt = [ordered]@{ schema='dcoir.pr_exact_head_validation.v1'; pr_number=469; requested_sha=$requestedSha; actual_sha=$actualSha; validation_command_count=$commands.Count; total_executions=$results.Count; preflight_v43_passed=$preflightPassed; passed_count=$passedCount; failed_count=$failedCount; worktree_dirty=$worktreeDirty; dirty_paths=$dirtyPaths; inference_credentials_removed=$inferenceEnv; live_model_inference=$false; live_dcoir_review_invocation=$false; result=$resultText; commands=$results }
  ($receipt | ConvertTo-Json -Depth 8) | Out-File -LiteralPath $receiptPath -Encoding utf8
  @('# PR #469 exact-head deterministic validation','',('- Requested SHA: `' + $requestedSha + '`'),('- Actual SHA: `' + $actualSha + '`'),('- Governed validation commands: ' + $commands.Count),('- Total executions including v43 preflight: ' + $results.Count),('- Passed: ' + $passedCount),('- Failed: ' + $failedCount),('- Worktree dirty: ' + $worktreeDirty),('- Live model inference: false'),('- Live /dcoir-review invocation: false')) | Out-File -LiteralPath $summaryPath -Encoding utf8

  if ($failedCount -ne 0) { throw "deterministic validation failed: $failedCount of $($results.Count) executions failed" }
  if ($worktreeDirty) { throw ('deterministic validation dirtied the worktree: ' + ($dirtyPaths -join ', ')) }
  if (-not $preflightPassed) { throw 'v43 preflight failed' }
  Write-Output "PR #469 exact-head deterministic validation passed: $passedCount/$($results.Count), requested=$requestedSha actual=$actualSha, worktree clean, inference credentials removed."
}
catch {
  $message = $_.Exception.Message
  if (-not (Test-Path -LiteralPath $receiptPath)) {
    $passedCount = @($results | Where-Object { $_.exit_code -eq 0 }).Count
    $failedCount = $results.Count - $passedCount
    $failureReceipt = @{ schema='dcoir.pr_exact_head_validation.v1'; pr_number=469; requested_sha=$requestedSha; actual_sha=$actualSha; validation_command_count=$commands.Count; total_executions=$results.Count; passed_count=$passedCount; failed_count=$failedCount; inference_credentials_removed=$inferenceEnv; live_model_inference=$false; live_dcoir_review_invocation=$false; result='failure'; error=$message }
    ($failureReceipt | ConvertTo-Json -Depth 5) | Out-File -LiteralPath $receiptPath -Encoding utf8
  }
  Write-Error $message
  exit 1
}
finally {
  Set-Location -LiteralPath $repo
  if (Test-Path -LiteralPath $worktree) {
    & git -C $repo worktree remove --force $worktree 2>$null
    if (Test-Path -LiteralPath $worktree) { Remove-Item -LiteralPath $worktree -Recurse -Force -ErrorAction SilentlyContinue }
  }
}
